import { Card, Container,Row,Button } from "react-bootstrap";
import './ProjectCard.css'
import './BlogCard.css'
import { Link, useNavigate } from "react-router-dom";
import { parseTimestampString } from "../Parser";
import { useEffect, useState } from "react";
import styled, { css } from "styled-components";
import markdownToTxt from 'markdown-to-text';
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import rehypeKatex from "rehype-katex";

export default function BlogCard({post, imgsrc, hasMax, useMarkdown}) {
    const navigate = useNavigate();
    const maxChar = 180;
    function slugurl() {
        return "/blog/" + post.slug;
    }

    function cutContent() {
        if (hasMax == 'false') return post.content;
        let str = post.content;
        if (post.content.length > maxChar) str = post.content.substring(0,maxChar) + "...";
        return str;
    }
    return (
        <Card  className="projectCard blogCard h-100" as={Link} to={slugurl()}>
            <Card.Img variant="top" src={imgsrc}></Card.Img>
            <Card.Body className="cardBody" style={{zIndex:"1", backgroundColor:"inherit"}}>
                <Card.Title>{post.title}</Card.Title>
                <Card.Subtitle>{parseTimestampString(post.date)}</Card.Subtitle>

                <Card.Text>
                    {useMarkdown == "true" ? <Markdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]}>{cutContent()}</Markdown> : markdownToTxt(cutContent()) }
                </Card.Text>
            </Card.Body>
        </Card>
    );
}